#include <stdio.h>
#include <stdlib.h>
#include <limits.h>

#define MAXN 1005
#define INF 1000000000

int x1[MAXN], y1[MAXN], x2[MAXN], y2[MAXN];
int parent[MAXN], rnk[MAXN];

int find(int a) {
    while (parent[a] != a) {
        parent[a] = parent[parent[a]];
        a = parent[a];
    }
    return a;
}

void unite(int a, int b) {
    a = find(a);
    b = find(b);
    if (a == b) return;
    if (rnk[a] < rnk[b]) {
        parent[a] = b;
    } else if (rnk[a] > rnk[b]) {
        parent[b] = a;
    } else {
        parent[b] = a;
        rnk[a]++;
    }
}

int max(int a, int b) {
    return a > b ? a : b;
}

int min(int a, int b) {
    return a < b ? a : b;
}

int absi(int a) {
    return a < 0 ? -a : a;
}

int pointRectDist(int px, int py, int i) {
    int dx = 0, dy = 0;
    if (px < x1[i]) dx = x1[i] - px;
    else if (px > x2[i]) dx = px - x2[i];

    if (py < y1[i]) dy = y1[i] - py;
    else if (py > y2[i]) dy = py - y2[i];

    return dx + dy;
}

int rectRectDist(int i, int j) {
    int dx = max(0, max(x1[i], x1[j]) - min(x2[i], x2[j]));
    int dy = max(0, max(y1[i], y1[j]) - min(y2[i], y2[j]));
    return dx + dy;
}

int main() {
    int Xi, Yi, Xf, Yf;
    if (scanf("%d %d %d %d", &Xi, &Yi, &Xf, &Yf) != 4) return 0;

    int N;
    scanf("%d", &N);

    for (int i = 0; i < N; i++) {
        scanf("%d %d %d %d", &x1[i], &y1[i], &x2[i], &y2[i]);
    }

    for (int i = 0; i < N; i++) {
        parent[i] = i;
        rnk[i] = 0;
    }

    for (int i = 0; i < N; i++) {
        for (int j = i + 1; j < N; j++) {
            if (max(x1[i], x1[j]) <= min(x2[i], x2[j]) &&
                max(y1[i], y1[j]) <= min(y2[i], y2[j])) {
                unite(i, j);
            }
        }
    }

    int compIdx[MAXN];
    int rootMap[MAXN];
    for (int i = 0; i < N; i++) rootMap[i] = -1;

    int K = 0;
    for (int i = 0; i < N; i++) {
        int r = find(i);
        if (rootMap[r] == -1) rootMap[r] = K++;
        compIdx[i] = rootMap[r];
    }

    int startDist[MAXN], targetDist[MAXN];
    for (int c = 0; c < K; c++) {
        startDist[c] = INF;
        targetDist[c] = INF;
    }

    for (int i = 0; i < N; i++) {
        int c = compIdx[i];

        int d = pointRectDist(Xi, Yi, i);
        if (d < startDist[c]) startDist[c] = d;

        d = pointRectDist(Xf, Yf, i);
        if (d < targetDist[c]) targetDist[c] = d;
    }

    int compDist[MAXN][MAXN];
    for (int i = 0; i < K; i++) {
        for (int j = 0; j < K; j++) {
            compDist[i][j] = INF;
        }
    }

    for (int i = 0; i < N; i++) {
        for (int j = i + 1; j < N; j++) {
            int ci = compIdx[i];
            int cj = compIdx[j];
            if (ci != cj) {
                int d = rectRectDist(i, j);
                if (d < compDist[ci][cj]) {
                    compDist[ci][cj] = d;
                    compDist[cj][ci] = d;
                }
            }
        }
    }

    int V = K + 2;
    int S = K;
    int T = K + 1;

    int dist[MAXN];
    int vis[MAXN];

    for (int i = 0; i < V; i++) {
        dist[i] = INF;
        vis[i] = 0;
    }

    dist[S] = 0;

    int direct = absi(Xi - Xf) + absi(Yi - Yf);

    for (int it = 0; it < V; it++) {
        int u = -1;
        int best = INF;

        for (int v = 0; v < V; v++) {
            if (!vis[v] && dist[v] < best) {
                best = dist[v];
                u = v;
            }
        }

        if (u == -1) break;
        vis[u] = 1;

        if (u == S) {
            for (int c = 0; c < K; c++) {
                if (dist[S] + startDist[c] < dist[c]) {
                    dist[c] = dist[S] + startDist[c];
                }
            }
            if (dist[S] + direct < dist[T]) {
                dist[T] = dist[S] + direct;
            }
        } else if (u == T) {
            for (int c = 0; c < K; c++) {
                if (dist[T] + targetDist[c] < dist[c]) {
                    dist[c] = dist[T] + targetDist[c];
                }
            }
            if (dist[T] + direct < dist[S]) {
                dist[S] = dist[T] + direct;
            }
        } else {
            int c = u;
            for (int d = 0; d < K; d++) {
                if (d == c) continue;
                if (dist[c] + compDist[c][d] < dist[d]) {
                    dist[d] = dist[c] + compDist[c][d];
                }
            }
            if (dist[c] + startDist[c] < dist[S]) {
                dist[S] = dist[c] + startDist[c];
            }
            if (dist[c] + targetDist[c] < dist[T]) {
                dist[T] = dist[c] + targetDist[c];
            }
        }
    }

    printf("%d\n", dist[T]);

    return 0;
}
